/**
 * E2E Tests for Session Stream — Tool Call Collapsed-by-Default Behavior
 *
 * Covered ACs:
 * - @ui-session-stream ac-1: Tool calls rendered as collapsible blocks,
 *   collapsed by default regardless of status.
 *
 * Task: @01KK3BSWT9NQHKEZ19P97VT3SV
 */

import { test, expect } from '../fixtures/test-base';

/** Mock session detail for a live session. */
function mockSessionDetail(status: 'active' | 'completed' = 'completed') {
	return {
		id: '01JTEST0000000000000000010',
		status,
		agent_type: 'task-worker',
		session_type: 'invocation',
		trigger: 'task.ready',
		task_id: '01JTASK0000000000000000010',
		started_at: '2026-03-06T10:00:00.000Z',
		ended_at: status === 'completed' ? '2026-03-06T11:00:00.000Z' : undefined,
		duration_ms: status === 'completed' ? 3600000 : 60000,
		event_count: 5,
		iteration_count: 1,
		tasks_completed: status === 'completed' ? 1 : 0,
	};
}

/** Mock events including tool calls in various states. */
function mockEvents() {
	return {
		events: [
			{
				seq: 1,
				type: 'session.start',
				ts: 1741258800000,
				data: { agent_type: 'task-worker' },
			},
			{
				seq: 2,
				type: 'session.update',
				ts: 1741258801000,
				data: {
					sessionUpdate: 'tool_call',
					toolCallId: 'tc-001',
					title: 'Read',
					rawInput: { file_path: '/src/index.ts' },
				},
			},
			{
				seq: 3,
				type: 'session.update',
				ts: 1741258802000,
				data: {
					sessionUpdate: 'tool_result',
					toolCallId: 'tc-001',
					rawOutput: 'file contents here',
					status: 'completed',
				},
			},
			{
				seq: 4,
				type: 'session.update',
				ts: 1741258803000,
				data: {
					sessionUpdate: 'tool_call',
					toolCallId: 'tc-002',
					title: 'Bash',
					rawInput: { command: 'npm test' },
				},
			},
			// tc-002 intentionally left as 'running' (no result event)
		],
		total: 4,
	};
}

const SESSION_ID = '01JTEST0000000000000000010';

test.describe('Session Stream — Tool Call Default State', () => {
	// AC: @ui-session-stream ac-1 — Tool calls collapsed by default
	test('completed tool calls render collapsed by default', async ({ page, daemon }) => {
		await page.route(`**/api/sessions/${SESSION_ID}`, (route) => {
			route.fulfill({
				status: 200,
				contentType: 'application/json',
				body: JSON.stringify(mockSessionDetail('completed')),
			});
		});
		await page.route(`**/api/sessions/${SESSION_ID}/events**`, (route) => {
			route.fulfill({
				status: 200,
				contentType: 'application/json',
				body: JSON.stringify(mockEvents()),
			});
		});

		await page.goto(`/sessions/${SESSION_ID}`);
		await expect(page.getByTestId('session-stream')).toBeVisible({ timeout: 5000 });

		const toolCalls = page.getByTestId('tool-call-block');
		await expect(toolCalls).toHaveCount(2);

		// Both tool calls should be collapsed (aria-expanded="false")
		const firstButton = toolCalls.nth(0).locator('button[aria-expanded]');
		const secondButton = toolCalls.nth(1).locator('button[aria-expanded]');
		await expect(firstButton).toHaveAttribute('aria-expanded', 'false');
		await expect(secondButton).toHaveAttribute('aria-expanded', 'false');
	});

	// AC: @ui-session-stream ac-1 — Running tool calls also collapsed by default
	test('running tool calls render collapsed by default in live sessions', async ({ page, daemon }) => {
		await page.route(`**/api/sessions/${SESSION_ID}`, (route) => {
			route.fulfill({
				status: 200,
				contentType: 'application/json',
				body: JSON.stringify(mockSessionDetail('active')),
			});
		});
		await page.route(`**/api/sessions/${SESSION_ID}/events**`, (route) => {
			route.fulfill({
				status: 200,
				contentType: 'application/json',
				body: JSON.stringify(mockEvents()),
			});
		});

		await page.goto(`/sessions/${SESSION_ID}`);
		await expect(page.getByTestId('session-stream')).toBeVisible({ timeout: 5000 });

		const toolCalls = page.getByTestId('tool-call-block');
		await expect(toolCalls).toHaveCount(2);

		// The second tool call is 'running' — it should still be collapsed
		const runningButton = toolCalls.nth(1).locator('button[aria-expanded]');
		await expect(runningButton).toHaveAttribute('aria-expanded', 'false');
	});

	// AC: @ui-session-stream ac-1 — User can expand and collapse tool calls
	test('clicking a collapsed tool call expands it', async ({ page, daemon }) => {
		await page.route(`**/api/sessions/${SESSION_ID}`, (route) => {
			route.fulfill({
				status: 200,
				contentType: 'application/json',
				body: JSON.stringify(mockSessionDetail('completed')),
			});
		});
		await page.route(`**/api/sessions/${SESSION_ID}/events**`, (route) => {
			route.fulfill({
				status: 200,
				contentType: 'application/json',
				body: JSON.stringify(mockEvents()),
			});
		});

		await page.goto(`/sessions/${SESSION_ID}`);
		await expect(page.getByTestId('session-stream')).toBeVisible({ timeout: 5000 });

		const firstToolCall = page.getByTestId('tool-call-block').nth(0);
		const toggleButton = firstToolCall.locator('button[aria-expanded]');

		// Initially collapsed
		await expect(toggleButton).toHaveAttribute('aria-expanded', 'false');

		// Click to expand
		await toggleButton.click();
		await expect(toggleButton).toHaveAttribute('aria-expanded', 'true');

		// Click to collapse again
		await toggleButton.click();
		await expect(toggleButton).toHaveAttribute('aria-expanded', 'false');
	});

	// AC: @ui-session-stream ac-1 — Expand state preserved across periodic refresh
	test('user-expanded tool call stays expanded after periodic refresh', async ({ page, daemon }) => {
		let requestCount = 0;

		await page.route(`**/api/sessions/${SESSION_ID}`, (route) => {
			route.fulfill({
				status: 200,
				contentType: 'application/json',
				body: JSON.stringify(mockSessionDetail('active')),
			});
		});
		await page.route(`**/api/sessions/${SESSION_ID}/events**`, (route) => {
			requestCount++;
			route.fulfill({
				status: 200,
				contentType: 'application/json',
				body: JSON.stringify(mockEvents()),
			});
		});

		await page.goto(`/sessions/${SESSION_ID}`);
		await expect(page.getByTestId('session-stream')).toBeVisible({ timeout: 5000 });

		const firstToolCall = page.getByTestId('tool-call-block').nth(0);
		const toggleButton = firstToolCall.locator('button[aria-expanded]');

		// Expand the first tool call
		await toggleButton.click();
		await expect(toggleButton).toHaveAttribute('aria-expanded', 'true');

		// Wait for at least one periodic refresh cycle (3s interval + buffer)
		const initialCount = requestCount;
		await page.waitForFunction(
			() => true,
			null,
			{ timeout: 5000, polling: 500 },
		);
		// Wait for the refresh to actually fire
		await expect(async () => {
			expect(requestCount).toBeGreaterThan(initialCount);
		}).toPass({ timeout: 5000 });

		// After refresh, the tool call should still be expanded
		await expect(toggleButton).toHaveAttribute('aria-expanded', 'true');
	});
});

