  2→  AC: @ui-session-stream ac-1 — Tool calls rendered as collapsible blocks with icon, input/output, timing.
  3→-->
  4→<script lang="ts">
  5→	import type { ToolCallBlock } from './session-utils';
  6→	import { getToolIcon, getToolInputPreview, formatDuration, formatTime } from './session-utils';
  7→	import ChevronRight from '@lucide/svelte/icons/chevron-right';
  8→	import Check from '@lucide/svelte/icons/check';
  9→	import X from '@lucide/svelte/icons/x';
 10→	import Loader from '@lucide/svelte/icons/loader';
 11→
 12→	let { block }: { block: ToolCallBlock } = $props();
 13→
 14→	let expanded = $state(block.status === 'running');
 15→
 16→	let borderColor = $derived(
 17→		block.status === 'completed'
 18→			? 'border-l-status-completed'
 19→			: block.status === 'failed'
 20→				? 'border-l-status-blocked'
 21→				: 'border-l-status-pending-review'
 22→	);
 23→
 24→	let icon = $derived(getToolIcon(block.toolName));
 25→	let preview = $derived(getToolInputPreview(block.toolName, block.input));
 26→
 27→	function formatOutput(output: unknown): string {
 28→		if (typeof output === 'string') return output;
 29→		try {
 30→			return JSON.stringify(output, null, 2);
 31→		} catch {
 32→			return String(output);
 33→		}
 34→	}
 35→
 36→	function formatInput(input: unknown): string {
 37→		if (typeof input === 'string') return input;
 38→		try {
 39→			return JSON.stringify(input, null, 2);
 40→		} catch {
 41→			return String(input);
 42→		}
 43→	}
 44→
 45→	let outputText = $derived(block.output ? formatOutput(block.output) : '');
 46→	let truncatedOutput = $derived(
 47→		outputText.length > 1000 ? outputText.slice(0, 1000) : outputText
 48→	);
 49→	let isOutputTruncated = $derived(outputText.length > 1000);
 50→	let showFullOutput = $state(false);
 51→</script>
 52→
 53→<div
 54→	class="border-l-2 {borderColor} rounded-r-md bg-card/50"
 55→	data-testid="tool-call-block"
 56→	data-tool-call-id={block.toolCallId}
 57→>
 58→	<!-- AC: @ui-session-stream ac-5 — Header enforces single-line layout with truncation -->
 59→	<button
 60→		class="flex items-center gap-2 w-full px-3 py-2 text-left text-sm hover:bg-accent/30 transition-colors overflow-hidden"
 61→		onclick={() => (expanded = !expanded)}
 62→		aria-expanded={expanded}
 63→	>
 64→		<ChevronRight
 65→			class="size-3.5 flex-shrink-0 text-muted-foreground transition-transform {expanded ? 'rotate-90' : ''}"
 66→		/>
 67→
 68→		<span class="text-xs text-muted-foreground font-mono flex-shrink-0 whitespace-nowrap">{formatTime(block.startedAt)}</span>
 69→
 70→		<span class="inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-xs font-mono bg-secondary min-w-0 max-w-[40%]">
 71→			<span class="flex-shrink-0">{icon}</span>
 72→			<span class="truncate">{block.toolName}</span>
 73→		</span>
 74→
 75→		{#if block.status === 'running'}
 76→			<Loader class="size-3.5 flex-shrink-0 text-status-pending-review ds-tool-spin" />
 77→		{:else if block.status === 'completed'}
 78→			<Check class="size-3.5 flex-shrink-0 text-status-completed" />
 79→		{:else if block.status === 'failed'}
 80→			<X class="size-3.5 flex-shrink-0 text-status-blocked" />
 81→		{/if}
 82→
 83→		{#if !expanded && preview}
 84→			<span class="text-xs text-muted-foreground truncate min-w-0">{preview}</span>
 85→		{/if}
 86→
 87→		{#if block.durationMs !== undefined}
 88→			<span class="text-[10px] text-muted-foreground font-mono ml-auto flex-shrink-0 whitespace-nowrap">
 89→				{formatDuration(block.durationMs)}
 90→			</span>
 91→		{/if}
 92→	</button>
 93→
 94→	<!-- Expanded content -->
 95→	{#if expanded}
 96→		<div class="px-3 pb-3 space-y-2">
 97→			{#if block.input}
 98→				<div>
 99→					<p class="text-[10px] font-medium text-muted-foreground uppercase tracking-wide mb-1">Input</p>
100→					<pre class="text-xs font-mono bg-secondary/50 rounded p-2 overflow-x-auto max-h-60 whitespace-pre-wrap break-words">{formatInput(block.input)}</pre>
101→				</div>
102→			{/if}
103→
104→			{#if block.output !== undefined}
105→				<div>
106→					<p class="text-[10px] font-medium text-muted-foreground uppercase tracking-wide mb-1">
107→						Output
108→						{#if block.status === 'failed'}
109→							<span class="text-destructive">(error)</span>
110→						{/if}
111→					</p>
112→					<pre class="text-xs font-mono bg-secondary/50 rounded p-2 overflow-x-auto max-h-80 whitespace-pre-wrap break-words {block.status === 'failed' ? 'text-destructive' : ''}">{showFullOutput ? outputText : truncatedOutput}</pre>
113→					{#if isOutputTruncated && !showFullOutput}
114→						<button
115→							class="text-xs text-primary hover:underline mt-1"
116→							onclick={() => (showFullOutput = true)}
117→						>
118→							Show full output ({outputText.length.toLocaleString()} chars)
119→						</button>
120→					{/if}
121→				</div>
122→			{/if}
123→		</div>
124→	{/if}
125→</div>
126→
127→<style>
128→	@keyframes tool-spin {
129→		from { transform: rotate(0deg); }
130→		to { transform: rotate(360deg); }
131→	}
132→	:global(.ds-tool-spin) {
133→		animation: tool-spin 1.5s linear infinite;
134→	}
135→	@media (prefers-reduced-motion: reduce) {
136→		:global(.ds-tool-spin) {
137→			animation: none;
138→		}
139→	}
